import threading
from collections import OrderedDict
import unittest


class LRUCache:
    """Least Recently Used Cache implementation using OrderedDict."""

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("Capacity must be positive")
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        """Get value for key, moving it to end (most recently used)."""
        if key not in self.cache:
            return None
        # Move to end to mark as recently used
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        """Put key-value pair, evicting LRU item if at capacity."""
        if key in self.cache:
            # Update existing key and move to end
            self.cache.move_to_end(key)
        self.cache[key] = value
        # Evict least recently used if over capacity
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

    def delete(self, key):
        """Delete key from cache. Returns True if deleted, False if not found."""
        if key in self.cache:
            del self.cache[key]
            return True
        return False

    def __len__(self):
        """Return current number of items in cache."""
        return len(self.cache)


class ThreadSafeLRUCache:
    """Thread-safe wrapper around LRUCache using a lock."""

    def __init__(self, capacity: int):
        self._cache = LRUCache(capacity)
        self._lock = threading.Lock()

    def get(self, key):
        with self._lock:
